'use client'

import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ButtonHTMLAttributes,
} from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'
import { playHoverSound, playClickSound } from '@/lib/sound'
export interface CheckboxProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange'> {
  checked?: boolean
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
  label?: string
  indeterminate?: boolean
  name?: string
  disabled?: boolean
  required?: boolean
  strikeThrough?: boolean
  'aria-invalid'?: boolean
  'aria-describedby'?: string
}

export const Checkbox = forwardRef<HTMLButtonElement, CheckboxProps>(
  (
    {
      checked: checkedProp,
      defaultChecked = false,
      onCheckedChange,
      label,
      indeterminate = false,
      name,
      disabled,
      required,
      strikeThrough = false,
      className,
      id: idProp,
      'aria-invalid': ariaInvalid,
      'aria-describedby': ariaDescribedby,
      ...props
    },
    ref,
  ) => {
    const reactId = useId()
    const id = idProp ?? reactId
    const isControlled = checkedProp !== undefined
    const [internal, setInternal] = useState(defaultChecked)
    const value = isControlled ? checkedProp : internal
    const reduceMotion = useReducedMotion()

    const isFirstRenderRef = useRef(true)
    useEffect(() => {
      isFirstRenderRef.current = false
    }, [])

    const toggle = useCallback(() => {
      if (disabled) return
      playClickSound()
      if (indeterminate) {
        if (!isControlled) setInternal(true)
        onCheckedChange?.(true)
      } else {
        const next = !value
        if (!isControlled) setInternal(next)
        onCheckedChange?.(next)
      }
    }, [value, indeterminate, isControlled, onCheckedChange, disabled])

    const inputRef = useCallback(
      (node: HTMLInputElement | null) => {
        if (node) node.indeterminate = indeterminate
      },
      [indeterminate],
    )

    const isChecked = indeterminate ? false : value
    const ariaChecked = indeterminate ? 'mixed' : value
    const showGlyph = indeterminate || value
    // eslint-disable-next-line react-hooks/refs
    const skipDrawIn = isFirstRenderRef.current || !!reduceMotion

    return (
      <div className="flex items-center gap-3">
        <input
          ref={inputRef}
          type="checkbox"
          id={id}
          name={name}
          checked={isChecked}
          disabled={disabled}
          required={required}
          readOnly
          className="sr-only"
          tabIndex={-1}
        />
        <button
          ref={ref}
          type="button"
          role="checkbox"
          aria-checked={ariaChecked}
          aria-label={label}
          aria-invalid={ariaInvalid}
          aria-describedby={ariaDescribedby}
          disabled={disabled}
          onClick={toggle}
          onMouseEnter={() => {
            if (!disabled) playHoverSound()
          }}
          className={cn(
            'flex size-5 shrink-0 items-center justify-center rounded-[5px] squircle-corners border transition-[color,background-color,border-color,transform]',
            'active:scale-[0.97] motion-reduce:active:scale-100',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-2 focus-visible:ring-offset-(--color-bg)',
            'disabled:cursor-not-allowed disabled:opacity-50',
            value
              ? 'border-(--color-fg) bg-(--color-fg) text-(--color-bg)'
              : 'border-(--color-border) bg-transparent text-transparent',
            ariaInvalid && 'border-(--color-error)',
            className,
          )}
          onPointerDown={(e) => e.preventDefault()}
          {...props}
        >
          <svg
            width="12"
            height="12"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={3}
            strokeLinecap="round"
            strokeLinejoin="round"
            className="shrink-0"
          >
            <AnimatePresence>
              {showGlyph &&
                (indeterminate ? (
                  <motion.path
                    key="dash"
                    d="M5 12h14"
                    initial={skipDrawIn ? false : { pathLength: 0, pathOffset: 0.5 }}
                    animate={{ pathLength: 1, pathOffset: 0 }}
                    exit={{ pathLength: 0, pathOffset: 0.5 }}
                    transition={reduceMotion ? { duration: 0 } : springs.settle}
                  />
                ) : (
                  <motion.path
                    key="check"
                    d="M5 12.5l4.5 4.5L19 7.5"
                    initial={skipDrawIn ? false : { pathLength: 0 }}
                    animate={{ pathLength: 1 }}
                    exit={{ pathLength: 1 }}
                    transition={reduceMotion ? { duration: 0 } : springs.settle}
                  />
                ))}
            </AnimatePresence>
          </svg>
        </button>
        {label && (
          <label
            htmlFor={id}
            className="min-h-11 flex items-center text-sm select-none"
            onClick={toggle}
          >
            {strikeThrough ? (
              <span
                className={cn(
                  'relative inline-block transition-colors duration-(--motion-dur-base) ease-(--motion-ease-out)',
                  value ? 'text-(--color-muted)' : 'text-(--color-fg)',
                )}
              >
                {label}
                <motion.span
                  aria-hidden="true"
                  className="absolute left-0 right-0 top-1/2 h-px bg-current motion-reduce:transition-none"
                  style={{ transformOrigin: 'left' }}
                  initial={false}
                  animate={{ scaleX: value ? 1 : 0 }}
                  transition={reduceMotion ? { duration: 0 } : springs.settle}
                />
              </span>
            ) : (
              <span className="text-(--color-fg)">{label}</span>
            )}
          </label>
        )}
      </div>
    )
  },
)
Checkbox.displayName = 'Checkbox'
export function CheckboxPreview() {
  const [checked, setChecked] = useState(false)
  const [todoChecked, setTodoChecked] = useState(false)
  return (
    <div className="flex h-full w-full items-center justify-center p-6">
      <div className="space-y-3">
        <Checkbox checked={checked} onCheckedChange={setChecked} label="Accept terms" />
        <Checkbox indeterminate label="Indeterminate" />
        <Checkbox checked disabled label="Disabled" />
        <Checkbox
          checked={todoChecked}
          onCheckedChange={setTodoChecked}
          label="Buy groceries"
          strikeThrough
        />
      </div>
    </div>
  )
}

export const durations = {
  instant: '50ms',
  fast: '120ms',
  base: '200ms',
  slow: '320ms',
} as const

export const easings = {
  out: 'cubic-bezier(0.22, 1, 0.36, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
} as const

export const springs = {
  fast: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
  press: { type: 'spring', stiffness: 700, damping: 32, mass: 1 },
  moderate: { type: 'spring', stiffness: 300, damping: 24, mass: 1 },
  settle: { type: 'spring', stiffness: 260, damping: 26, mass: 1 },
} as const

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
